window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-718d1fa3fe3bcf93"]={"versions": [{"id": "FIG-718d1fa3fe3bcf93", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architekturschaubild / Methodikdiagramm zur Veranschaulichung von Subsystem-Sichten (Views) im Rahmen der AUTOSAR-Methodik. Das Diagramm illustriert, wie aus einer gemeinsamen Gesamtarchitektur („Common Software Architecture“) durch Extraktionsschritte teilspezifische Sichten abgeleitet werden, um heterogene Systemkontexte – insbesondere die Koexistenz von AUTOSAR Adaptive Platform (AP) und AUTOSAR Classic Platform (CP) – beherrschbar zu machen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten gliedern sich in drei Hauptblöcke sowie zwei Transformationsschritte:</p>\n<ul class=\"fig-list\">\n<li><strong>Common Software Architecture</strong>: Umfassende Architekturebene bestehend aus Adaptive Applications (<code>AApl1</code>, <code>AApl5</code>), Classic Software Components (<code>SWC 2</code>, <code>SWC 3</code>, <code>SWC 4</code>) und deren Ports. Dargestellt sind direkte Software-Konnektoren (durchgezogene Linien) zwischen <code>SWC 2</code> und <code>SWC 4</code> sowie zwischen <code>SWC 3</code> und <code>SWC 4</code>, sowie plattformübergreifende Interaktionsbeziehungen (gestrichelte Linien) zwischen <code>AApl1</code> und <code>SWC 3</code>.</li>\n<li><strong>AP/CP Mixed View</strong>: Abgeleitete Teilsicht, die ausschließlich die Schnittstellenpartner der gemischten Kommunikation (<code>AApl1</code>, <code>AApl5</code>, <code>SWC 3</code>) und die zugehörige logische Verbindung zwischen <code>AApl1</code> und <code>SWC 3</code> umfasst.</li>\n<li><strong>VFB View (Virtual Function Bus View)</strong>: Abgeleitete Classic-Platform-Sicht, welche die Classic-Komponenten <code>SWC 2</code>, <code>SWC 3</code> und <code>SWC 4</code> mit ihren wechselseitigen Port-Verbindungen umfasst.</li>\n<li><strong>Transformationsoperatoren</strong>: Abgerundete Callout-Knoten <code>Generate System Extract AP/CP Mixed View</code> und <code>Generate System Extract VFB</code>, welche die Filter- bzw. Projektionsschritte der Systemextraktion repräsentieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keinen zeitlichen Ablauf dar, sondern eine modellbasierte Strukturtransformation:</p>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Gesamtsystemmodell (<code>Common Software Architecture</code>) werden über automatisierte oder werkzeuggestützte Transformationsschritte Teilmodelle (System Extracts) generiert.</li>\n<li>Der linke Transformationspfad (<code>Generate System Extract AP/CP Mixed View</code>) selektiert adaptive und klassische Entitäten, die in plattformübergreifenden Informationsaustausch eingebunden sind.</li>\n<li>Der rechte Transformationspfad (<code>Generate System Extract VFB</code>) isoliert die reine Classic-VFB-Kommunikation für die klassische AUTOSAR-Entwicklungskette.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm hat methodisch-erläuternden Charakter (informative Guidance) zur Reduktion von Modellkomplexität in heterogenen Gesamtfahrzeugarchitekturen. Es verdeutlicht für Systemarchitekten und Tool-Entwickler, dass Softwarekomponenten und deren Interaktionen nicht zwingend monolithisch verarbeitet werden müssen, sondern über standardisierte System-Extracts auf technologiespezifische Engineering-Workflows (Classic VFB Tooling vs. Adaptive/Classic-Integrationswerkzeuge) projiziert werden können. Die Port-Definitionen und Schnittstellenbeziehungen der Komponenten müssen in der Common Software Architecture plattformkonsistent definiert sein, damit abgeleitete Sichten widerspruchsfrei instanziiert werden können.</p>"}, {"id": "FIG-2d288efa3c893e9d", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architekturschaubild / Methodikdiagramm zur Veranschaulichung von Subsystem-Sichten (Views) im Rahmen der AUTOSAR-Methodik. Das Diagramm illustriert, wie aus einer gemeinsamen Gesamtarchitektur („Common Software Architecture“) durch Extraktionsschritte teilspezifische Sichten abgeleitet werden, um heterogene Systemkontexte – insbesondere die Koexistenz von AUTOSAR Adaptive Platform (AP) und AUTOSAR Classic Platform (CP) – beherrschbar zu machen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten gliedern sich in drei Hauptblöcke sowie zwei Transformationsschritte:</p>\n<ul class=\"fig-list\">\n<li><strong>Common Software Architecture</strong>: Umfassende Architekturebene bestehend aus Adaptive Applications (<code>AApl1</code>, <code>AApl5</code>), Classic Software Components (<code>SWC 2</code>, <code>SWC 3</code>, <code>SWC 4</code>) und deren Ports. Dargestellt sind direkte Software-Konnektoren (durchgezogene Linien) zwischen <code>SWC 2</code> und <code>SWC 4</code> sowie zwischen <code>SWC 3</code> und <code>SWC 4</code>, sowie plattformübergreifende Interaktionsbeziehungen (gestrichelte Linien) zwischen <code>AApl1</code> und <code>SWC 3</code>.</li>\n<li><strong>AP/CP Mixed View</strong>: Abgeleitete Teilsicht, die ausschließlich die Schnittstellenpartner der gemischten Kommunikation (<code>AApl1</code>, <code>AApl5</code>, <code>SWC 3</code>) und die zugehörige logische Verbindung zwischen <code>AApl1</code> und <code>SWC 3</code> umfasst.</li>\n<li><strong>VFB View (Virtual Function Bus View)</strong>: Abgeleitete Classic-Platform-Sicht, welche die Classic-Komponenten <code>SWC 2</code>, <code>SWC 3</code> und <code>SWC 4</code> mit ihren wechselseitigen Port-Verbindungen umfasst.</li>\n<li><strong>Transformationsoperatoren</strong>: Abgerundete Callout-Knoten <code>Generate System Extract AP/CP Mixed View</code> und <code>Generate System Extract VFB</code>, welche die Filter- bzw. Projektionsschritte der Systemextraktion repräsentieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt keinen zeitlichen Ablauf dar, sondern eine modellbasierte Strukturtransformation:</p>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Gesamtsystemmodell (<code>Common Software Architecture</code>) werden über automatisierte oder werkzeuggestützte Transformationsschritte Teilmodelle (System Extracts) generiert.</li>\n<li>Der linke Transformationspfad (<code>Generate System Extract AP/CP Mixed View</code>) selektiert adaptive und klassische Entitäten, die in plattformübergreifenden Informationsaustausch eingebunden sind.</li>\n<li>Der rechte Transformationspfad (<code>Generate System Extract VFB</code>) isoliert die reine Classic-VFB-Kommunikation für die klassische AUTOSAR-Entwicklungskette.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm hat methodisch-erläuternden Charakter (informative Guidance) zur Reduktion von Modellkomplexität in heterogenen Gesamtfahrzeugarchitekturen. Es verdeutlicht für Systemarchitekten und Tool-Entwickler, dass Softwarekomponenten und deren Interaktionen nicht zwingend monolithisch verarbeitet werden müssen, sondern über standardisierte System-Extracts auf technologiespezifische Engineering-Workflows (Classic VFB Tooling vs. Adaptive/Classic-Integrationswerkzeuge) projiziert werden können. Die Port-Definitionen und Schnittstellenbeziehungen der Komponenten müssen in der Common Software Architecture plattformkonsistent definiert sein, damit abgeleitete Sichten widerspruchsfrei instanziiert werden können.</p>"}], "trans": [{"from": "FIG-718d1fa3fe3bcf93", "to": "FIG-2d288efa3c893e9d", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
